        return grid

    rows, cols = len(grid), len(grid[0])

    # Count all colors
    counts = {}
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    # Background is most common
