                                    visited[nr][nc] = True
                                    stack.append((nr, nc))
                    comp_count += 1
        component_counts[color] = comp_count

    # Source = color with most components (> 1)
    source = max([c for c, cnt in component_counts.items() if cnt > 1], key=lambda x: counts[x]) if any(c > 1 for c in component_counts.values()) else others[0]

    # Target = other non-bg color (prioritize by count)
