                comp = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == source and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                min_r = min(x[0] for x in comp)
                min_c = min(x[1] for x in comp)
                source_components.append((min_r, min_c, comp))

    # Sort by top-left coordinate and pick first
    source_components.sort(key=lambda x: (x[0], x[1]))

    if source_components:
        new_grid = [row[:] for row in grid]
        _, _, top_left_comp = source_components[0]
        for r, c in top_left_comp:
            new_grid[r][c] = target
        return new_grid

    return grid
